describe('Ayuda sobre un intento persistido en el Ryzen', () => {
  it('H01 Consultar la fuente y reabrir la ayuda → conserva el diagnóstico y guarda un reintento nuevo', () =>
    prepare('H01').then((context) => {
      let requestsBeforeSave = 0;
      cy.intercept('POST', '**/api/v1/attempts/*/feedback-requests', () => {
        requestsBeforeSave++;
      });
      cy.get(sel('attempt-help')).should('not.exist');
      return submit(context, context.wrongCode, 'FAILED_TEST').then((first) => {
        firstAttemptId = first.attemptId;
        expect(requestsBeforeSave).to.equal(0);
        edit(context.correctCode);
        return requestHelp(context, first.attemptId, 'FEEDBACK').then(
          ({ requestId }) => {
            openHelp('SUPPORTED');
            expect(context.source).not.to.equal(null);
            cy.get(sel('help-reference'))
              .should('contain.text', context.source!.title)
              .and('contain.text', 'versión 1');
            cy.get(sel('help-reference-locator')).should(
              'contain.text',
              'Líneas',
            );
            cy.get(sel('help-reference-text')).should(
              'contain.text',
              context.source!.text,
            );
            cy.intercept('GET', '**/api/v1/feedback/*/sources/*/content').as(
              'sourceBytes',
            );
            cy.get(sel('download-help-source')).first().click();
            cy.wait('@sourceBytes', {
              log: false,
              responseTimeout: 45000,
            }).then(({ response }) => {
              expect(response?.statusCode).to.equal(200);
              expect(response?.headers['cache-control']).to.include('no-store');
              expect(response?.body).to.equal(context.source!.text);
            });
            cy.reload();
            cy.get(sel('show-attempt')).first().click();
            openHelp('SUPPORTED');
            verifyHelp(
              context,
              first.attemptId,
              requestId,
              'SUPPORTED',
              'FEEDBACK',
            );
            return retry(context, first);
          },
        );
      });
    }));
  it('H02 Pedir ayuda sin material → conserva el borrador y permite un reintento sin inventar fuentes', () =>
    prepare('H02').then((context) => {
      expect(context.source).to.equal(null);
      cy.get(sel('attempt-help')).should('not.exist');
      return submit(context, context.wrongCode, 'FAILED_TEST').then((first) => {
        firstAttemptId = first.attemptId;
        edit(context.correctCode);
        return requestHelp(context, first.attemptId, 'HINT').then(
          ({ requestId }) => {
            openHelp('NO_EVIDENCE');
            verifyHelp(
              context,
              first.attemptId,
              requestId,
              'NO_EVIDENCE',
              'HINT',
            );
            return retry(context, first);
          },
        );
      });
    }));
  it('H03 Recuperar la ayuda tras una falla → mantiene la pista 1 y guarda otra solución sin perder el intento original', () =>
    prepare('H03').then((context) =>
      submit(context, context.wrongCode, 'FAILED_TEST').then((first) => {
        firstAttemptId = first.attemptId;
        edit(context.correctCode);
        task('fault', {
          scope: context.scope,
          attemptId: first.attemptId,
          enabled: true,
        });
        return requestHelp(context, first.attemptId, 'HINT').then((failed) => {
          openHelp('PROVIDER_UNAVAILABLE');
          verifyHelp(
            context,
            first.attemptId,
            failed.requestId,
            'PROVIDER_UNAVAILABLE',
            'HINT',
          );
          task('fault', {
            scope: context.scope,
            attemptId: first.attemptId,
            enabled: false,
          });
          return requestHelp(context, first.attemptId, 'HINT').then(
            (recovered) => {
              expect(recovered.requestId).not.to.equal(failed.requestId);
              expect(recovered.key).not.to.equal(failed.key);
              openHelp('SUPPORTED');
              cy.get(sel('help-hint')).should('not.be.empty');
              cy.get(sel('help-reference')).should(
                'contain.text',
                context.source!.title,
              );
              cy.get(sel('request-hint')).should(
                'contain.text',
                'Pedir pista 2 de 3',
              );
              verifyHelp(
                context,
                first.attemptId,
                recovered.requestId,
                'SUPPORTED',
                'HINT',
              );
              return retry(context, first);
            },
          );
        });
      }),
    ));
});
